WITH rels AS (SELECT oid,relname FROM pg_class WHERE relnamespace='public'::regnamespace AND relname IN ('chip_ledger','rake_records','table_seats','tables','tournament_escrow','tournament_obligations','tournament_payouts','tournament_players','tournament_rake_settlements','tournament_satellite_awards','tournament_satellite_settlements','tournament_tickets','tournaments','wallet_transactions','wallets')) SELECT jsonb_build_object('columns',(SELECT jsonb_agg(jsonb_build_object('table',r.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid))) FROM rels r JOIN pg_attribute a ON a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=r.oid AND d.adnum=a.attnum),'constraints',(SELECT jsonb_agg(jsonb_build_object('table',r.relname,'name',c.conname,'definition',pg_get_constraintdef(c.oid))) FROM rels r JOIN pg_constraint c ON c.conrelid=r.oid),'indexes',(SELECT jsonb_agg(jsonb_build_object('table',r.relname,'name',i.indexname,'definition',i.indexdef)) FROM rels r JOIN pg_indexes i ON i.schemaname='public' AND i.tablename=r.relname),'triggers',(SELECT jsonb_agg(jsonb_build_object('table',r.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled,'function',t.tgfoid::regprocedure::text,'body_md5',md5(p.prosrc))) FROM rels r JOIN pg_trigger t ON t.tgrelid=r.oid AND NOT t.tgisinternal JOIN pg_proc p ON p.oid=t.tgfoid));